code.css:
.hc-checks{margin-top:var(--s5)}
.hc-checks:empty{display:none}
.hc-item{display:flex;gap:var(--s3);align-items:flex-start;padding:11px 0;
  border-top:1px solid var(--line);font-size:var(--t-14);line-height:1.45}
.hc-mark{flex:0 0 20px;height:20px;border-radius:50%;display:grid;place-items:center;
  font:500 12px/1 var(--font-sans);margin-top:1px}
.hc-ok .hc-mark{background:var(--ok-bg);color:var(--ok);border:1px solid var(--ok-line)}
.hc-warn .hc-mark{background:var(--danger-bg);color:var(--danger);border:1px solid var(--danger-line)}
.hc-warn{color:var(--ink)}
.hc-item b{font-weight:500}
.hc-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}
.hc-tags span{font-family:var(--font-mono);font-size:var(--t-12);
  background:var(--surface-2);border:1px solid var(--line);border-radius:var(--r-sm);padding:2px 6px}
#cap{min-height:200px}

code.js:
(function(){
  var $=function(id){return document.getElementById(id)};
  var P={
  instagram:{n:'Instagram',tags:30,chars:2200,note:'30 hashtags and 2,200 characters. Only the first 125 characters show before the More link.'},
  tiktok:{n:'TikTok',tags:20,chars:2200,note:'2,200 characters including the hashtags. Three to six tags is normal.'},
  x:{n:'X / Twitter',tags:10,chars:280,note:'280 characters for most accounts. One or two hashtags perform best.'},
  linkedin:{n:'LinkedIn',tags:10,chars:3000,note:'3,000 characters, and only the first 140 or so show before See more.'},
  youtube:{n:'YouTube',tags:15,chars:5000,note:'Only the first three hashtags appear above the title. Past 15 they are all ignored.'},
  facebook:{n:'Facebook',tags:10,chars:63206,note:'Effectively no limit, but posts over 80 characters get less engagement.'},
  pinterest:{n:'Pinterest',tags:20,chars:500,note:'500 characters. Hashtags act as keywords rather than links.'}
};
  $('plat').innerHTML=Object.keys(P).map(function(k){
    return '<option value="'+k+'"'+(k==='instagram'?' selected':'')+'>'+P[k].n+'</option>';
  }).join('');

  function tagsIn(text){
    // a hashtag is # then letters, numbers or underscore. Numbers alone are
    // not a hashtag on any platform, which is a common surprise.
    var m=text.match(/#[\p{L}\p{N}_]+/gu)||[];
    return m.map(function(t){return t.slice(1)});
  }
  function run(){
    var text=$('cap').value, p=P[$('plat').value];
    var tags=tagsIn(text);
    var lower=tags.map(function(t){return t.toLowerCase()});
    var chars=Array.from(text).length;
    $('ntag').textContent=tags.length;
    $('nchar').textContent=chars;
    $('nleft').textContent=Math.max(0,p.chars-chars);
    var cut = $('plat').value==='instagram'?125:($('plat').value==='linkedin'?140:0);
    $('nvis').textContent = cut ? Math.min(chars,cut) : 'all';

    var checks=[];
    function add(ok,label,extra){ checks.push({ok:ok,label:label,extra:extra||''}); }

    add(tags.length<=p.tags,
      tags.length<=p.tags
        ? tags.length+' hashtag'+(tags.length===1?'':'s')+', within the '+p.tags+' that '+p.n+' allows.'
        : '<b>'+tags.length+' hashtags is over the limit.</b> '+p.n+' allows '+p.tags+', so '+(tags.length-p.tags)+' will be ignored or the post may be rejected.');

    add(chars<=p.chars,
      chars<=p.chars
        ? chars+' characters, inside the '+p.chars.toLocaleString()+' limit.'
        : '<b>'+chars+' characters is over the '+p.chars.toLocaleString()+' limit</b> by '+(chars-p.chars)+'.');

    var dupes={}, repeated=[];
    lower.forEach(function(t){ dupes[t]=(dupes[t]||0)+1; });
    Object.keys(dupes).forEach(function(t){ if(dupes[t]>1) repeated.push(t); });
    add(!repeated.length,
      repeated.length
        ? '<b>'+repeated.length+' hashtag'+(repeated.length===1?' appears':'s appear')+' more than once.</b> Repeats do not help and waste your allowance.'
        : 'No repeated hashtags.',
      repeated.length?repeated.map(function(t){return '#'+t}).join(' '):'');

    var longOnes=tags.filter(function(t){return t.length>24});
    add(!longOnes.length,
      longOnes.length
        ? longOnes.length+' hashtag'+(longOnes.length===1?' is':'s are')+' very long. Nobody reads or searches these, and they eat your character count.'
        : 'No overly long hashtags.',
      longOnes.length?longOnes.map(function(t){return '#'+t}).join(' '):'');

    var numeric=tags.filter(function(t){return /^[0-9]+$/.test(t)});
    add(!numeric.length,
      numeric.length
        ? '<b>'+numeric.length+' hashtag'+(numeric.length===1?' is':'s are')+' numbers only</b>, which no platform treats as a hashtag.'
        : 'Every hashtag has letters in it.',
      numeric.length?numeric.map(function(t){return '#'+t}).join(' '):'');

    if(cut){
      add(chars<=cut || text.indexOf('#')>cut,
        text.indexOf('#')>=0 && text.indexOf('#')<cut
          ? 'Your hashtags start inside the first '+cut+' characters, so they show in the preview before anyone taps More. Moving them to the end usually reads better.'
          : 'Your first '+cut+' characters are clean, which is what shows in the feed before the More link.');
    }

    $('checks').innerHTML=checks.map(function(c){
      return '<div class="hc-item '+(c.ok?'hc-ok':'hc-warn')+'"><span class="hc-mark">'+(c.ok?'\u2713':'!')+'</span>'+
        '<div>'+c.label+(c.extra?'<div class="hc-tags">'+c.extra.split(' ').map(function(t){return '<span>'+t+'</span>'}).join('')+'</div>':'')+'</div></div>';
    }).join('');
    $('note').textContent=p.note;
    if(window.WT) WT.resize();
  }
  ['cap','plat'].forEach(function(id){ $(id).addEventListener('input',run); $(id).addEventListener('change',run); });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('cap').value);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy caption'},1400);
  });
  $('strip').addEventListener('click',function(){
    $('cap').value=$('cap').value.replace(/#[\p{L}\p{N}_]+/gu,'').replace(/[ \t]{2,}/g,' ').replace(/\n{3,}/g,'\n\n').trim();
    run();
  });
  $('clear').addEventListener('click',function(){ $('cap').value=''; run(); });
  run();
})();
